for(const [code,map] of Object.entries(fullPatch)) Object.assign(fullDetail[code]??={},map);
for(const [code,map] of Object.entries(effectPatch)) Object.assign(fullDetail[code]??={},map);
const allEnglish = [...english, ...extraEnglish, ...fullEnglish, ...fullPatchEnglish];
const completeRows = Object.fromEntries(languages.filter(([code])=>code!=='en').map(([code])=>{
  const detail=fullDetail[code];
  return [code,[...(rows[code]||english),...(extraRows[code]||extraEnglish),...fullEnglish,...fullPatchEnglish].map((value,index)=>detail?.[allEnglish[index]] ?? value)];
}));
export const translationCatalog={languages,english:allEnglish,rows:completeRows};
const phraseMap = new Map([[english[0], Object.fromEntries(languages.map(([code])=>[code,english[0]]))]]);
for (let i=0;i<allEnglish.length;i++) phraseMap.set(allEnglish[i],Object.fromEntries([['en',allEnglish[i]],...Object.entries(completeRows).map(([code,values])=>[code,values[i]])]));
const attributeAliases = new Map([
  ['Conversation','Conversations'],
  ['Messages','Message'],
  ['Edit my profile','Your profile'],
  ['Device storage notice','Storage details'],
  ['Privacy policy','Privacy']
]);

export function getPreference(key) { try { return localStorage.getItem(key); } catch { return null; } }
export function setPreference(key,value) { try { localStorage.setItem(key,value); return true; } catch { return false; } }
export function languageCode() {
  const saved=getPreference('illusion-language');
  if (languages.some(([code])=>code===saved)) return saved;
  const browser=(navigator.languages||[navigator.language||'en']).map(x=>String(x).toLowerCase());
  for(const value of browser){const match=languages.find(([code])=>code.toLowerCase()===value||value.startsWith(code.toLowerCase()+'-'));if(match)return match[0];const base=value.split('-')[0],baseMatch=languages.find(([code])=>code.toLowerCase().split('-')[0]===base);if(baseMatch)return baseMatch[0];}
  return 'en';
}
export function translate(text,language=languageCode()) {
  if(language==='en')return text;
  return phraseMap.get(text)?.[language]||phraseMap.get(attributeAliases.get(text))?.[language]||text;
}
const staticText=new Map(),staticAttributes=new Map();
export function applyStaticLanguage(language=languageCode()) {
  const lang=language.toLowerCase();document.documentElement.lang=lang;document.documentElement.dir=language==='ar'?'rtl':'ltr';
  if(!staticText.size){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let text;while((text=walker.nextNode()))if(text.nodeValue.trim())staticText.set(text,text.nodeValue);}
  for(const [text,base] of staticText){const original=base.trim();text.nodeValue=base.replace(original,translate(original,language));}
  if(!staticAttributes.size)for(const element of document.querySelectorAll('[aria-label],[title],[placeholder]'))for(const attr of ['aria-label','title','placeholder'])if(element.hasAttribute(attr))staticAttributes.set([element,attr],element.getAttribute(attr));
  for(const [[element,attr],base] of staticAttributes)element.setAttribute(attr,translate(base,language));
}
export function languageOptions() { return languages.map(([code,name])=>({code,name})); }
